        // ─── Privacy page ─────────────────────────────────────────────────────
        // The English text in PRIVACY.md stays the authoritative version; this is a convenience
        // translation of the same wording, kept line for line so the two can be compared.
        ["Pv_Back"] = ("Back", "Kembali"),
        ["Pv_EffectiveDate"] = ("Effective date: June 9, 2026", "Berlaku sejak: 9 Juni 2026"),
        ["Pv_Tldr"] = ("TL;DR", "Ringkasnya"),
        ["Pv_TldrBody"] = ("The app does not collect, transmit, sell, or share any personal data about you. There are no analytics, no advertising, no third-party tracking SDKs, and no developer-owned servers receiving anything about you or your usage. Everything you configure stays on your device.", "Aplikasi ini tidak mengumpulkan, mengirim, menjual, atau membagikan data pribadi Anda. Tidak ada analitik, tidak ada iklan, tidak ada SDK pelacak pihak ketiga, dan tidak ada server milik pengembang yang menerima apa pun tentang Anda atau pemakaian Anda. Semua yang Anda atur tetap di perangkat Anda."),
        ["Pv_WhatItDoes"] = ("What this app does and doesn't do with your data", "Apa yang dilakukan dan tidak dilakukan aplikasi ini dengan data Anda"),
        ["Pv_WhatItDoesBody"] = ("When you log in and whenever a scheduled run starts, the app loads TikTok in an Android WebView and uses your own cookies to open chat threads and send the message you configured. TikTok's own privacy policy applies to whatever happens inside that WebView.", "Saat Anda login dan setiap kali jadwal berjalan, aplikasi memuat TikTok di WebView Android dan memakai cookie Anda sendiri untuk membuka percakapan dan mengirim pesan yang Anda atur. Kebijakan privasi TikTok sendiri berlaku untuk apa pun yang terjadi di dalam WebView itu."),
        ["Pv_Network"] = ("Network connections", "Koneksi jaringan"),
        ["Pv_NetworkBody"] = ("The app communicates directly with the following services from your device. The developer does not operate any intermediary server and does not see this traffic:", "Aplikasi berkomunikasi langsung dengan layanan berikut dari perangkat Anda. Pengembang tidak menjalankan server perantara dan tidak melihat lalu lintas ini:"),
        ["Pv_NetworkTiktok"] = ("Connect to TikTok to send streaks and to GitHub for update checks; detect Wi-Fi / cellular availability before starting a run.",
            "Terhubung ke TikTok untuk mengirim streak dan ke GitHub untuk memeriksa pembaruan; mendeteksi ketersediaan Wi-Fi / seluler sebelum mulai berjalan."),
        ["Pv_NetworkGithub"] = ("For the in-app 'Check for updates' feature. The app calls the public GitHub Releases API for repo PATRICK297R/Tiktok-Streak-Saver and downloads APK files from release assets. The only header sent is 'User-Agent: TiktokStreakSaver/1.0'. No account, device, or personal identifiers are sent.", "Untuk fitur 'Periksa pembaruan' di dalam aplikasi. Aplikasi memanggil API publik GitHub Releases untuk repo PATRICK297R/Tiktok-Streak-Saver dan mengunduh berkas APK dari aset rilis. Satu-satunya header yang dikirim adalah 'User-Agent: TiktokStreakSaver/1.0'. Tidak ada akun, perangkat, atau identitas pribadi yang dikirim."),
        ["Pv_NetworkEnd"] = ("That is the entire set of outbound connections. There are no analytics endpoints, no crash-reporting endpoints, no advertising endpoints.",
            "Itulah seluruh koneksi keluar. Tidak ada endpoint analitik, tidak ada endpoint pelaporan crash, tidak ada endpoint iklan."),
        ["Pv_Stored"] = ("What the app stores on your device", "Apa yang disimpan aplikasi di perangkat Anda"),
        ["Pv_StoredBody"] = ("The following information is saved on your device using Android's standard preferences and the system WebView cookie store. It never leaves your device unless you back it up or export it yourself:", "Informasi berikut disimpan di perangkat Anda memakai preferensi standar Android dan penyimpanan cookie WebView sistem. Tidak pernah keluar dari perangkat Anda kecuali Anda sendiri mencadangkan atau mengekspornya:"),
        ["Pv_Security"] = ("Security", "Keamanan"),
        ["Pv_SecurityBody"] = ("Local data is kept inside the app's private storage, protected by Android's standard app-sandboxing model. Because nothing is transmitted to a developer-controlled server, there is no remote breach risk on the developer's side.", "Data lokal disimpan di penyimpanan privat aplikasi, dilindungi model sandbox standar Android. Karena tidak ada yang dikirim ke server yang dikendalikan pengembang, tidak ada risiko kebocoran dari sisi pengembang."),
        ["Pv_ThirdParties"] = ("Third parties", "Pihak ketiga"),
        ["Pv_ThirdPartiesBody"] = ("The app does not embed any third-party advertising, analytics, attribution, marketing, or social SDKs. The only services it talks to are TikTok (your own account) and GitHub (public release metadata), each with their own privacy practices, which apply to your direct interaction with them.", "Aplikasi tidak menyertakan SDK iklan, analitik, atribusi, pemasaran, atau media sosial pihak ketiga. Layanan yang dihubungi hanya TikTok (akun Anda sendiri) dan GitHub (metadata rilis publik), masing-masing dengan praktik privasinya sendiri yang berlaku atas interaksi langsung Anda dengan mereka."),
        ["Pv_Permissions"] = ("Permissions and why they are requested", "Izin dan alasan permintaannya"),
        ["Pv_PermInternetWhy"] = ("Connect to TikTok to send streaks and to GitHub for update checks; detect Wi-Fi / cellular availability before starting a run.",
            "Terhubung ke TikTok untuk mengirim streak dan ke GitHub untuk memeriksa pembaruan; mendeteksi ketersediaan Wi-Fi / seluler sebelum mulai berjalan."),
        ["Pv_PermAlarmWhy"] = ("Trigger the next streak run at the configured time.", "Memicu pengiriman streak berikutnya pada jam yang Anda atur."),
        ["Pv_PermBootWhy"] = ("Reschedule the alarm after the device restarts.", "Menjadwalkan ulang alarm setelah perangkat dinyalakan kembali."),
        ["Pv_PermBatteryWhy"] = ("Ask Android to keep the app reliable in the background.", "Meminta Android menjaga aplikasi tetap andal di latar belakang."),
        ["Pv_PermForegroundWhy"] = ("Keep the streak-sender service alive while a run is in progress.", "Menjaga layanan pengirim streak tetap hidup saat pengiriman berlangsung."),
        ["Pv_PermNotificationsWhy"] = ("Show progress and completion notifications.", "Menampilkan notifikasi kemajuan dan penyelesaian."),
        ["Pv_PermInstallWhy"] = ("Install updated APKs downloaded from GitHub Releases.", "Memasang APK pembaruan yang diunduh dari GitHub Releases."),
        ["Pv_PermEnd"] = ("The app uses these permissions only for the purposes listed above.", "Aplikasi memakai izin ini hanya untuk keperluan yang disebutkan di atas."),
        ["Pv_Changes"] = ("Changes", "Perubahan"),
        ["Pv_ChangesBody"] = ("Updates to this policy are committed to PRIVACY.md in the repository and reflected in the in-app Privacy screen on the next app update. The Effective date above changes whenever the text changes.", "Pembaruan kebijakan ini dicatat di PRIVACY.md pada repositori dan ditampilkan di layar Privasi aplikasi pada pembaruan berikutnya. Tanggal berlaku di atas berubah setiap kali teksnya berubah."),
        ["Pv_Contact"] = ("Contact", "Kontak"),
        ["Pv_ContactBody"] = ("This app is maintained on GitHub. To report a privacy concern, open an issue on the project's GitHub Issues page.",
            "Aplikasi ini dikelola di GitHub. Untuk melaporkan masalah privasi, buka issue di halaman GitHub Issues proyek."),
        ["Pv_OpenIssues"] = ("Open GitHub Issues", "Buka GitHub Issues"),
        ["Pv_ViewOnGithub"] = ("View on GitHub", "Lihat di GitHub"),
        ["Pv_MinimumAge"] = ("Minimum Age", "Usia Minimum"),
        ["Pv_MinimumAgeBody"] = ("The app is not intended for users below the age of 13 or your region's age requirements for TikTok.",
            "Aplikasi ini tidak ditujukan untuk pengguna di bawah usia 13 tahun atau batas usia TikTok di wilayah Anda."),
        ["Pv_Erase"] = ("You can erase all of this at any time by tapping 'Logout / Clear Session' on the Profile page, or by going to Android Settings → Apps → Streak Saver → Storage → Clear data, or by uninstalling the app.", "Anda bisa menghapus semuanya kapan saja dengan menekan 'Keluar / Hapus Sesi' di halaman Profil, atau lewat Pengaturan Android → Aplikasi → Streak Saver → Penyimpanan → Hapus data, atau dengan menghapus pemasangan aplikasi."),
        ["Pv_StoredList"] = ("TikTok session cookies, the friend and group list, custom messages, schedule settings, run history, and the run log.",
            "Cookie sesi TikTok, daftar teman dan grup, pesan khusus, pengaturan jadwal, riwayat pengiriman, dan log pengiriman."),
        ["Pv_StoredBullet1"] = ("• TikTok session data: cookies and the browser user-agent string captured at login, so background runs can send streak messages without re-logging in.", "• Data sesi TikTok: cookie dan string user-agent browser yang diambil saat login, agar pengiriman di latar belakang bisa mengirim pesan streak tanpa login ulang."),
        ["Pv_StoredBullet2"] = ("• The friends and groups list you add: TikTok usernames, optional display names, group names, enable/disable state, and counters (last-sent timestamp, success/failure counts).", "• Daftar teman dan grup yang Anda tambahkan: nama pengguna TikTok, nama tampilan opsional, nama grup, status aktif/nonaktif, dan penghitung (waktu kirim terakhir, jumlah berhasil/gagal)."),
        ["Pv_StoredBullet3"] = ("• Your custom message text and the randomized-messages toggle.", "• Teks pesan khusus Anda dan tombol pesan acak."),
        ["Pv_StoredBullet4"] = ("• Scheduling preferences: interval or fixed daily time, retry counter for the day, the 'Send streaks if battery is running low' toggle, and similar app settings.", "• Preferensi jadwal: interval atau jam harian tetap, penghitung percobaan ulang hari itu, tombol 'Kirim streak bila baterai hampir habis', dan pengaturan aplikasi serupa."),
        ["Pv_StoredBullet5"] = ("• Run history: per-run results (success/failure per friend), capped to the most recent 50 runs.", "• Riwayat pengiriman: hasil tiap pengiriman (berhasil/gagal per teman), dibatasi sampai 50 pengiriman terakhir."),
        ["Pv_StoredBullet6"] = ("• Optional display name and profile photo you set in the app. The photo, if any, is stored as a file in the app's private storage.", "• Nama tampilan dan foto profil opsional yang Anda pasang di aplikasi. Fotonya, jika ada, disimpan sebagai berkas di penyimpanan privat aplikasi."),
        ["Pv_NetworkTiktokTitle"] = ("1. TikTok (tiktok.com and subdomains)", "1. TikTok (tiktok.com dan subdomainnya)"),
        ["Pv_NetworkGithubTitle"] = ("2. GitHub (api.github.com, github.com, and release-asset URLs)", "2. GitHub (api.github.com, github.com, dan URL aset rilis)"),
        ["Pv_OpenLinkTitle"] = ("Open Link", "Buka Tautan"),
        ["Pv_OpenLinkError"] = ("Could not open the link: {0}", "Tidak bisa membuka tautan: {0}"),

