        // iOS onboarding, limitations, Shortcut guide and platform text
        ["Ios_ReadFullDetails"] = ("Read full details", "Baca detail lengkap"),
        ["Ios_WelcomeTitle"] = ("Welcome to Streak Saver (iOS)", "Selamat datang di Streak Saver (iOS)"),
        ["Ios_WelcomeBody"] = ("This iOS build is experimental and not equivalent to Android. Streaks run through Shortcuts or the widget — not silent background alarms. The app must open briefly while TikTok runs in an invisible browser, and your iPhone must be unlocked when the automation fires.", "Build iOS ini eksperimental dan tidak setara dengan Android. Streak berjalan lewat Shortcuts atau widget — bukan alarm latar belakang senyap. Aplikasi harus terbuka sebentar saat TikTok berjalan di browser tak terlihat, dan iPhone Anda harus terbuka saat otomasi berjalan."),
        ["Ios_LimitsTitle"] = ("Know the limits", "Kenali batasannya"),
        ["Ios_LimitsBody"] = ("Shortcuts cannot launch Streak Saver while your phone is locked — you may see Unable to launch because the device couldn't be unlocked. iOS also suspends WebView automation in the background. For reliable daily streaks, use the Android app. Tap Read full details for Apple's official documentation links.", "Shortcuts tidak bisa membuka Streak Saver saat HP Anda terkunci — Anda mungkin melihat Unable to launch because the device couldn't be unlocked. iOS juga menangguhkan otomasi WebView di latar belakang. Untuk streak harian yang andal, pakai aplikasi Android. Ketuk Baca detail lengkap untuk tautan dokumentasi resmi Apple."),
        ["Ios_UnderstandContinue"] = ("I understand — continue", "Saya mengerti — lanjut"),
        ["Ios_SetUpShortcuts"] = ("Set up Shortcuts", "Siapkan Shortcuts"),
        ["Ios_SetUpShortcutsBody"] = ("Use the step-by-step guide with tabs for each screen on your phone. Schedule the automation for a time you are usually awake and unlocked.", "Pakai panduan langkah demi langkah dengan tab untuk setiap layar di HP Anda. Jadwalkan otomasi pada jam saat Anda biasanya terjaga dan HP terbuka."),
        ["Ios_OpenSetupGuide"] = ("Open setup guide", "Buka panduan penyiapan"),
        ["Ios_AltStoreTitle"] = ("AltStore & certificate", "AltStore & sertifikat"),
        ["Ios_AltStoreBody"] = ("This app is installed via AltStore. Free certificates expire every 7 days. Keep AltStore refreshing in the background so the app and Shortcuts keep working.", "Aplikasi ini dipasang lewat AltStore. Sertifikat gratis kedaluwarsa setiap 7 hari. Biarkan AltStore menyegarkan di latar belakang agar aplikasi dan Shortcuts tetap berfungsi."),
        ["Ios_Understand"] = ("I understand", "Saya mengerti"),
        ["Ios_NotificationsTitle"] = ("Notifications", "Notifikasi"),
        ["Ios_NotificationsBody"] = ("Allow notifications so you know when a streak run finishes or when you need to log in again.", "Izinkan notifikasi agar Anda tahu saat pengiriman streak selesai atau saat Anda perlu login lagi."),
        ["Ios_EnableNotifications"] = ("Enable notifications", "Aktifkan notifikasi"),
        ["Ios_WorksList"] = ("• Run Now when you open the app\n• Shortcuts automation when your iPhone is unlocked at the scheduled time\n• Widget tap after you unlock\n• Notifications when a run finishes or login is needed", "• Jalankan Sekarang saat Anda membuka aplikasi\n• Otomasi Shortcuts saat iPhone Anda terbuka pada jam yang dijadwalkan\n• Ketuk widget setelah Anda membuka HP\n• Notifikasi saat pengiriman selesai atau login diperlukan"),
        ["Ios_LimitsList"] = ("• Automation while the phone is locked — Shortcuts shows: Unable to launch because the device couldn't be unlocked\n• Silent background runs like Android — iOS suspends WebView JavaScript when backgrounded\n• In-app timers — scheduling is only through the Shortcuts app\n• Set-and-forget sideloading — AltStore certificates expire about every 7 days", "• Otomasi saat HP terkunci — Shortcuts menampilkan: Unable to launch because the device couldn't be unlocked\n• Pengiriman latar belakang senyap seperti Android — iOS menangguhkan JavaScript WebView saat di latar belakang\n• Timer di dalam aplikasi — penjadwalan hanya lewat aplikasi Shortcuts\n• Pasang sekali lalu lupakan — sertifikat AltStore kedaluwarsa sekitar setiap 7 hari"),
        ["Ios_NextProgress"] = ("Next ({0}/{1})", "Berikutnya ({0}/{1})"),
        ["Ios_ShortcutsTitle"] = ("Shortcuts", "Aplikasi Shortcuts"),
        ["Ios_OpenShortcutsManually"] = ("Open the Shortcuts app manually from your home screen.", "Buka aplikasi Shortcuts secara manual dari layar utama."),
        ["Ios_Step1Tab"] = ("Open", "Buka"),
        ["Ios_Step1Title"] = ("Open the Shortcuts app", "Buka aplikasi Shortcuts"),
        ["Ios_Step1Body"] = ("On your iPhone, open Shortcuts. Tap the Automation tab at the bottom (not the Shortcuts gallery).", "Di iPhone Anda, buka Shortcuts. Ketuk tab Automation di bagian bawah (bukan galeri Shortcuts)."),
        ["Ios_Step2Tab"] = ("New", "Baru"),
        ["Ios_Step2Title"] = ("Create a personal automation", "Buat otomasi pribadi"),
        ["Ios_Step2Body"] = ("Tap the + button (or Create Personal Automation). Choose Time of Day as the trigger.", "Ketuk tombol + (atau Create Personal Automation). Pilih Time of Day sebagai pemicunya."),
        ["Ios_Step3Tab"] = ("Daily", "Harian"),
        ["Ios_Step3Title"] = ("Set it to run every day", "Atur agar jalan setiap hari"),
        ["Ios_Step3Body"] = ("Pick Daily, choose the time you want streaks to run (match the time in Profile if you use a fixed schedule), then tap Next.", "Pilih Daily, tentukan jam Anda ingin streak dikirim (samakan dengan jam di Profil bila Anda memakai jadwal tetap), lalu ketuk Next."),
        ["Ios_Step4Tab"] = ("Action", "Aksi"),
        ["Ios_Step4Title"] = ("Add the Streak Saver action", "Tambahkan aksi Streak Saver"),
        ["Ios_Step4Body"] = ("Tap Add Action, search for Maintain TikTok Streaks, and select it from Streak Saver.", "Ketuk Add Action, cari Maintain TikTok Streaks, lalu pilih dari Streak Saver."),
        ["Ios_Step5Tab"] = ("Run", "Jalankan"),
        ["Ios_Step5Title"] = ("Turn off “Ask Before Running”", "Matikan “Ask Before Running”"),
        ["Ios_Step5Body"] = ("On the confirmation screen, disable Ask Before Running so the automation can fire on its own. Pick a daily time when your iPhone is usually unlocked — automations fail on a locked phone. Streak Saver will come to the foreground briefly while messages send in an invisible browser. Tap Done to save.", "Di layar konfirmasi, matikan Ask Before Running agar otomasi bisa jalan sendiri. Pilih jam harian saat iPhone Anda biasanya terbuka — otomasi gagal di HP yang terkunci. Streak Saver akan muncul sebentar di depan saat pesan dikirim di browser tak terlihat. Ketuk Done untuk menyimpan."),
        ["Ios_Step6Tab"] = ("Widget", "Widget"),
        ["Ios_Step6Title"] = ("Optional: home screen widget", "Opsional: widget layar utama"),
        ["Ios_Step6Body"] = ("Long-press the home screen → Add Widget → find Streak Saver. The widget runs the same action when you tap it (phone must be unlocked).", "Tekan lama layar utama → Add Widget → cari Streak Saver. Widget menjalankan aksi yang sama saat Anda ketuk (HP harus terbuka)."),
        ["Ios_Step7Tab"] = ("Limits", "Batasan"),
        ["Ios_Step7Title"] = ("iPhone must be unlocked", "iPhone harus terbuka"),
        ["Ios_Step7Body"] = ("Personal automations cannot launch Streak Saver while your phone is locked. If you see Unable to launch because the device couldn't be unlocked, schedule the automation for when you are usually awake and unlocked, or use Run Now after unlocking. This iOS build is experimental — Android is recommended for reliable background streaks. Profile → Why iOS is different for details.", "Otomasi pribadi tidak bisa membuka Streak Saver saat HP Anda terkunci. Bila Anda melihat Unable to launch because the device couldn't be unlocked, jadwalkan otomasi pada jam saat Anda biasanya terjaga dan HP terbuka, atau pakai Jalankan Sekarang setelah membuka HP. Build iOS ini eksperimental — Android lebih disarankan untuk streak latar belakang yang andal. Profil → Kenapa iOS berbeda untuk detailnya."),
        ["Ios_SendingMessages"] = ("Sending streak messages…", "Mengirim pesan streak…"),
        ["Ios_StaysOpenBriefly"] = ("Streak Saver stays open briefly while TikTok runs in an invisible browser — required on iOS.", "Streak Saver tetap terbuka sebentar saat TikTok berjalan di browser tak terlihat — wajib di iOS."),
        ["Ios_AlreadyRunning"] = ("A streak run is already in progress.", "Pengiriman streak sedang berjalan."),
        ["Ios_EngineMissing"] = ("Native streak engine is not available on this build. Rebuild the iOS app on macOS so StreakEngine.xcframework is embedded.", "Mesin streak native tidak tersedia di build ini. Build ulang aplikasi iOS di macOS agar StreakEngine.xcframework ikut tertanam."),
        ["Ios_FailedNoHistory"] = ("Streak run failed with no native history recorded.", "Pengiriman streak gagal tanpa riwayat native yang tercatat."),
        ["Ios_NoFriendsDue"] = ("No friends are due for a streak message today.", "Tidak ada teman yang perlu dikirimi pesan streak hari ini."),
        ["Ios_RunFinished"] = ("Run finished.", "Pengiriman selesai."),
        // Indonesian has no plural -s, so both keys read the same there; the split is kept because the
        // English column has to stay correct for the default language.
        ["Ios_SentOne"] = ("Sent {0} of {1} message.", "Terkirim {0} dari {1} pesan."),
        ["Ios_SentMany"] = ("Sent {0} of {1} messages.", "Terkirim {0} dari {1} pesan."),
        ["Ios_EngineExitedNoLogs"] = ("Native streak runner exited immediately with no logs. Rebuild the app so StreakEngine.xcframework is embedded.", "Runner streak native langsung berhenti tanpa log. Build ulang aplikasi agar StreakEngine.xcframework ikut tertanam."),
        ["Ios_NoNetwork"] = ("No network connection.", "Tidak ada koneksi jaringan."),
        ["Ios_NoCookies"] = ("TikTok session cookies are missing. Sign in again.", "Cookie sesi TikTok hilang. Silakan login lagi."),
        ["Ios_LoginRequired"] = ("TikTok login required. Sign in again.", "Perlu login TikTok. Silakan login lagi."),
        ["Ios_TimedOut"] = ("The streak run timed out. Try again.", "Pengiriman streak kehabisan waktu. Coba lagi."),
        ["Ios_SceneNotReady"] = ("The app window was not ready. Open Streak Saver and try again.", "Jendela aplikasi belum siap. Buka Streak Saver lalu coba lagi."),
        ["Ios_ScriptMissing"] = ("Automation script missing from the app bundle.", "Skrip otomasi tidak ada di bundel aplikasi."),
