    /// <summary>
    /// The string for a key. A key that is not in the table renders as the key with a leading marker, so a
    /// missing entry shows up in the interface instead of silently drawing nothing.
    /// </summary>
    public static string Get(string? key, AppLanguage language)
    {
        if (string.IsNullOrEmpty(key))
            return MissingKeyPrefix;

        if (!Table.TryGetValue(key, out var entry))
            return MissingKeyPrefix + key;

        var value = language == AppLanguage.Indonesian ? entry.Id : entry.En;

        // A blank translation falls back to English rather than leaving a hole in the layout.
        return string.IsNullOrEmpty(value) ? entry.En : value;
    }

    /// <summary>
    /// The language <see cref="T"/> looks up in.
    /// <para>
    /// <see cref="Localization"/> owns the choice - it is the one place that knows which language the
    /// interface is in - and pushes it here, so the MAUI-free classes that cannot see
    /// <see cref="Localization"/> (the shared services the pages and the background work both use) still
    /// render their text in the language the user picked. English until something sets it, which is what
    /// the tests see.
    /// </para>
    /// </summary>
    public static AppLanguage Language { get; private set; } = AppLanguage.English;

    /// <summary>Called by <see cref="Localization"/> when the stored choice is read or the user changes it.</summary>
    public static void SetLanguage(AppLanguage language) => Language = language;

    /// <summary>
    /// The string for a key in <see cref="Language"/>. For the code that cannot reach
    /// <see cref="Localization"/>; the pages use <see cref="Localization.T"/> so there is one spelling of
    /// "give me this text" in the interface code.
    /// </summary>
    public static string T(string key) => Get(key, Language);

    /// <summary>Whether a key is in the table. Used by the tests to prove every key exists.</summary>
    public static bool Has(string? key) => !string.IsNullOrEmpty(key) && Table.ContainsKey(key);

    /// <summary>
    /// The interface language a phone culture name means. <c>id</c>, <c>id-ID</c> and any other Indonesian
    /// region read as Indonesian; everything else reads as English.
    /// <para>
    /// A name rather than a <see cref="System.Globalization.CultureInfo"/> so this stays free of ambient
    /// state and the tests can pin it. Only the primary subtag is read: Indonesian has no regional
    /// variant the interface distinguishes, and the phone's exact region is not something the wording
    /// depends on.
    /// </para>
    /// </summary>
    public static AppLanguage FromCultureName(string? cultureName)
    {
        if (string.IsNullOrWhiteSpace(cultureName))
            return AppLanguage.English;

        var name = cultureName.Trim();

        // "id" or "id-ID"; the underscore spelling is the POSIX form some platforms still report.
        var separator = name.IndexOfAny(new[] { '-', '_' });
        var primary = separator > 0 ? name[..separator] : name;

        return string.Equals(primary, "id", StringComparison.OrdinalIgnoreCase)
            || string.Equals(primary, "in", StringComparison.OrdinalIgnoreCase)
                ? AppLanguage.Indonesian
                : AppLanguage.English;
    }

    /// <summary>Every key, for the tests that check the table is complete in both languages.</summary>
    public static IReadOnlyCollection<string> Keys => Table.Keys;

    /// <summary>The English wording, which is the source text every translation is checked against.</summary>
    public static string English(string key) => Table.TryGetValue(key, out var entry) ? entry.En : string.Empty;

    /// <summary>The Indonesian wording, for the tests that check nothing was left untranslated.</summary>
    public static string Indonesian(string key) => Table.TryGetValue(key, out var entry) ? entry.Id : string.Empty;
